CREATE TABLE accounts(id TEXT PRIMARY KEY,email TEXT UNIQUE,password_hash TEXT,role TEXT NOT NULL CHECK(role IN ('coach','client','admin')),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE clients(id TEXT PRIMARY KEY,account_id TEXT NOT NULL UNIQUE REFERENCES accounts(id),name TEXT NOT NULL,starting_weight REAL,height REAL,target_weight REAL,goal TEXT NOT NULL DEFAULT '',phase TEXT NOT NULL DEFAULT '',start_date TEXT NOT NULL,archived_at TEXT,avatar BLOB,avatar_type TEXT,longest_streak INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE assignments(coach_id TEXT NOT NULL REFERENCES accounts(id),client_id TEXT NOT NULL REFERENCES clients(id),active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(coach_id,client_id));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),csrf TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE invitations(token_hash TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients(id),expires_at TEXT NOT NULL,used_at TEXT);
CREATE TABLE exercises(id TEXT PRIMARY KEY,name TEXT NOT NULL,muscle TEXT NOT NULL,equipment TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('free_weight','machine','bodyweight','cardio')),active INTEGER NOT NULL DEFAULT 1,source TEXT,source_id TEXT,license TEXT,author TEXT,source_url TEXT,version INTEGER NOT NULL DEFAULT 1,UNIQUE(source,source_id));
CREATE UNIQUE INDEX exercise_identity ON exercises(lower(name),lower(muscle),lower(equipment),category);
CREATE TABLE plans(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients(id),coach_id TEXT NOT NULL REFERENCES accounts(id),name TEXT NOT NULL,start_date TEXT NOT NULL,phase TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',exercises_json TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE workouts(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients(id),plan_id TEXT REFERENCES plans(id),date TEXT NOT NULL,name TEXT NOT NULL,started_at TEXT,ended_at TEXT,note TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'in_progress' CHECK(status IN ('in_progress','completed','archived')),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX workout_day ON workouts(client_id,date) WHERE status <> 'archived';
CREATE TABLE workout_sets(id TEXT PRIMARY KEY,workout_id TEXT NOT NULL REFERENCES workouts(id),exercise_id TEXT NOT NULL REFERENCES exercises(id),exercise_name TEXT NOT NULL,muscle TEXT NOT NULL,equipment TEXT NOT NULL,category TEXT NOT NULL,position INTEGER NOT NULL,number INTEGER NOT NULL,planned_reps INTEGER,planned_weight REAL,planned_rpe REAL,actual_reps INTEGER,actual_weight REAL,rpe REAL CHECK(rpe IS NULL OR rpe BETWEEN 6 AND 10),rest_minutes REAL,warmup INTEGER NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '',completed INTEGER NOT NULL DEFAULT 0,duration_minutes REAL,distance_km REAL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE rest_days(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients(id),date TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',archived_at TEXT,created_at TEXT NOT NULL);
CREATE UNIQUE INDEX rest_day ON rest_days(client_id,date) WHERE archived_at IS NULL;
CREATE TRIGGER rest_excludes_workout BEFORE INSERT ON rest_days WHEN NEW.archived_at IS NULL AND EXISTS(SELECT 1 FROM workouts WHERE client_id=NEW.client_id AND date=NEW.date AND status<>'archived') BEGIN SELECT RAISE(ABORT,'day_conflict'); END;
CREATE TRIGGER workout_excludes_rest BEFORE INSERT ON workouts WHEN NEW.status<>'archived' AND EXISTS(SELECT 1 FROM rest_days WHERE client_id=NEW.client_id AND date=NEW.date AND archived_at IS NULL) BEGIN SELECT RAISE(ABORT,'day_conflict'); END;
CREATE TRIGGER workout_update_excludes_rest BEFORE UPDATE OF status,date ON workouts WHEN NEW.status<>'archived' AND EXISTS(SELECT 1 FROM rest_days WHERE client_id=NEW.client_id AND date=NEW.date AND archived_at IS NULL) BEGIN SELECT RAISE(ABORT,'day_conflict'); END;
CREATE TABLE daily_logs(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients(id),date TEXT NOT NULL,closed_at TEXT,data_json TEXT NOT NULL DEFAULT '{}',version INTEGER NOT NULL DEFAULT 1,UNIQUE(client_id,date));
CREATE TABLE food_logs(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients(id),date TEXT NOT NULL,meal INTEGER NOT NULL CHECK(meal BETWEEN 1 AND 6),name TEXT NOT NULL,grams REAL NOT NULL CHECK(grams>0),protein REAL,carbs REAL,fat REAL,calories REAL,created_at TEXT NOT NULL,archived_at TEXT);
CREATE TABLE measurements(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients(id),date TEXT NOT NULL,weight REAL NOT NULL CHECK(weight>0),data_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE notes(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients(id),author_id TEXT NOT NULL REFERENCES accounts(id),text TEXT NOT NULL,created_at TEXT NOT NULL,archived_at TEXT);
CREATE TABLE records(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients(id),kind TEXT NOT NULL CHECK(kind IN ('diet','medication','photo')),data_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,archived_at TEXT);
CREATE TABLE revisions(id TEXT PRIMARY KEY,entity TEXT NOT NULL,entity_id TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES accounts(id),before_json TEXT,after_json TEXT,created_at TEXT NOT NULL);
CREATE INDEX workout_client_date ON workouts(client_id,date);
CREATE INDEX set_workout ON workout_sets(workout_id,position,number);
CREATE INDEX revision_entity ON revisions(entity,entity_id,created_at);
CREATE INDEX food_client_date ON food_logs(client_id,date);
